<?php

declare(strict_types=1);

namespace App\Support;

use Illuminate\Support\HtmlString;

/**
 * Icons — SVG-иконки услуг/UI и логотипы марок.
 *
 * Иконки: Material Design Icons (Pictogrammers, Apache-2.0), viewBox 0 0 24 24,
 * заливка currentColor. Логотипы марок — реальные файлы в public/assets/img/brands/,
 * манифест slug => файл в app/Data/brand-logos.php. В покое монохромны (CSS
 * .brand-logo), в цвете — на ховере.
 */
final class Icons
{
    /** Иконка услуги по slug (фолбэк — diagnostika). */
    public static function service(string $slug, string $class = 'h-7 w-7'): HtmlString
    {
        $paths = self::servicePaths();
        $inner = $paths[$slug] ?? $paths['diagnostika'];

        return new HtmlString(self::svg($inner, $class));
    }

    /** UI-иконка: phone | telegram | form | location | clock | check. */
    public static function ui(string $name, string $class = 'h-6 w-6'): HtmlString
    {
        $inner = self::uiPaths()[$name] ?? '';

        return new HtmlString($inner === '' ? '' : self::svg($inner, $class));
    }

    /** Web-путь логотипа марки или null, если файла нет. */
    public static function brandLogo(string $slug): ?string
    {
        $file = self::brandMap()[$slug] ?? null;

        return $file ? asset('assets/img/brands/' . $file) : null;
    }

    /**
     * Эмблема марки: <img> с реальным логотипом (бел→цвет на ховере) либо
     * 2-буквенная монограмма-фолбэк.
     */
    public static function brandLogoImg(array $b, string $imgClass = 'h-9 w-9', string $monoClass = 'text-xl'): HtmlString
    {
        $slug = (string) ($b['slug'] ?? '');
        $name = (string) ($b['name'] ?? '');
        $src  = self::brandLogo($slug);

        if ($src !== null) {
            $html = '<img src="' . e($src) . '" alt="' . e($name) . ' логотип" loading="lazy" decoding="async"'
                . ' class="brand-logo ' . e($imgClass) . ' object-contain" />';

            return new HtmlString($html);
        }

        $mono = mb_substr($name, 0, 2, 'UTF-8');

        return new HtmlString('<span class="brand-mono ' . e($monoClass) . '">' . e($mono) . '</span>');
    }

    private static function svg(string $inner, string $class): string
    {
        return '<svg viewBox="0 0 24 24" aria-hidden="true" class="' . e($class) . '" fill="currentColor">'
            . $inner . '</svg>';
    }

    private static function brandMap(): array
    {
        static $map = null;

        return $map ??= require base_path('app/Data/brand-logos.php');
    }

